/* Results explorer: renders window.OFI_RESULTS (site/data.js, generated by `ofi site`) as plain SVG. */
(() => {
  "use strict";

  const D = window.OFI_RESULTS;
  const $ = (sel) => document.querySelector(sel);
  const SVG_NS = "http://www.w3.org/2000/svg";
  const MODEL_NAMES = { ofi: "OFI (main model)", ofi_over_depth: "OFI ÷ depth", ar1: "Last price change", ti: "Trade imbalance" };
  const state = { sym: "BTCUSDT" };

  // ---------- helpers ----------
  const css = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  const symColor = (sym) => css(`--${sym.slice(0, 3).toLowerCase()}`);
  const coin = (sym) => sym.replace(/USDT$/, "");
  const minus = (s) => s.replace(/^-/, "−");
  const fx = (v, d = 2) => (v === null || v === undefined || Number.isNaN(v) ? "–" : minus(Number(v).toFixed(d)));
  const signed = (v, d = 2) => (v > 0 ? "+" : "") + fx(v, d);
  const ci = (lo, hi, d = 2) => `[${fx(lo, d)}, ${fx(hi, d)}]`;
  const pct = (v, d = 0) => `${(v * 100).toFixed(d)}%`;
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

  function el(tag, attrs = {}, parent) {
    const node = document.createElementNS(SVG_NS, tag);
    for (const [k, v] of Object.entries(attrs)) if (v !== undefined && v !== null) node.setAttribute(k, v);
    if (parent) parent.appendChild(node);
    return node;
  }

  function text(parent, x, y, str, attrs = {}) {
    const t = el("text", { x, y, ...attrs }, parent);
    t.textContent = str;
    return t;
  }

  const linear = ([d0, d1], [r0, r1]) => {
    const s = (v) => r0 + ((v - d0) / (d1 - d0 || 1)) * (r1 - r0);
    s.invert = (p) => d0 + ((p - r0) / (r1 - r0 || 1)) * (d1 - d0);
    return s;
  };
  const logScale = ([d0, d1], range) => {
    const l = linear([Math.log10(d0), Math.log10(d1)], range);
    return (v) => l(Math.log10(v));
  };

  function frame(container, margin = { t: 12, r: 16, b: 34, l: 44 }) {
    container.replaceChildren();
    const w = Math.max(container.clientWidth, 260);
    const h = Math.max(container.clientHeight, 160);
    const svg = el("svg", { viewBox: `0 0 ${w} ${h}`, preserveAspectRatio: "none" }, container);
    return { svg, w, h, m: margin, x0: margin.l, x1: w - margin.r, y0: h - margin.b, y1: margin.t };
  }

  function emptyChart(container, message) {
    const f = frame(container);
    text(f.svg, f.w / 2, f.h / 2, message, { class: "empty", "text-anchor": "middle" });
  }

  function yAxis(f, y, ticks, format, title) {
    const g = el("g", { class: "axis" }, f.svg);
    for (const t of ticks) {
      el("line", { x1: f.x0, x2: f.x1, y1: y(t), y2: y(t), class: t === 0 ? "zero" : "gridline" }, g);
      text(g, f.x0 - 8, y(t) + 4, format(t), { "text-anchor": "end" });
    }
    if (title) text(g, 12, (f.y0 + f.y1) / 2, title, { class: "axis-title", transform: `rotate(-90 12 ${(f.y0 + f.y1) / 2})`, "text-anchor": "middle" });
  }

  // ---------- tooltip ----------
  const tip = $("#tooltip");
  function showTip(evt, html) {
    tip.innerHTML = html;
    tip.hidden = false;
    const pad = 14;
    const { innerWidth: vw, innerHeight: vh } = window;
    const r = tip.getBoundingClientRect();
    let x = evt.clientX + pad;
    let y = evt.clientY + pad;
    if (x + r.width > vw - 8) x = evt.clientX - r.width - pad;
    if (y + r.height > vh - 8) y = evt.clientY - r.height - pad;
    tip.style.left = `${Math.max(8, x)}px`;
    tip.style.top = `${Math.max(8, y)}px`;
  }
  const hideTip = () => { tip.hidden = true; };

  function hoverLayer(f, onMove, onLeave) {
    const r = el("rect", { x: f.x0, y: f.y1, width: f.x1 - f.x0, height: f.y0 - f.y1, fill: "transparent" }, f.svg);
    const toLocal = (evt) => {
      const box = f.svg.getBoundingClientRect();
      return [((evt.clientX - box.left) / box.width) * f.w, ((evt.clientY - box.top) / box.height) * f.h];
    };
    r.addEventListener("pointermove", (evt) => onMove(evt, ...toLocal(evt)));
    r.addEventListener("pointerdown", (evt) => onMove(evt, ...toLocal(evt)));
    r.addEventListener("pointerleave", () => { hideTip(); onLeave && onLeave(); });
    return r;
  }

  // ---------- hero ----------
  function renderHero() {
    const syms = D.symbols;
    const c = D.contemporaneous;
    const p = D.predictive;
    const r2 = syms.map((s) => c[s].r2[0]);
    const windows = syms.reduce((n, s) => n + c[s].windows, 0);
    const allPos = syms.every((s) => c[s].beta_pos_share === 1);
    const oos = syms.map((s) => p[s].oos_r2[0]);
    const be = syms.map((s) => p[s].break_even_bps);
    const best = Math.max(...oos);
    $("#hero-stats").innerHTML = `
      <div class="stat">
        <div class="stat__label explain">Explains · same 10 s</div>
        <div class="stat__value">${Math.round(Math.min(...r2) * 100)}–${Math.round(Math.max(...r2) * 100)}%</div>
        <p class="stat__text">of each 10-second price move is explained by order flow (median R² per symbol)${allPos ? `, with the expected positive sign in all ${windows.toLocaleString("en-US")} windows` : ""}.</p>
      </div>
      <div class="stat">
        <div class="stat__label predict">Predicts · next 10 s</div>
        <div class="stat__value">${best <= 0 ? "≤ 0" : fx(best, 4)}</div>
        <p class="stat__text">out-of-sample R² on the held-out days, for every symbol (${syms.map((s, i) => `${coin(s)} ${fx(oos[i], 4)}`).join(", ")}). Zero means no better than guessing "no change".</p>
      </div>
      <div class="stat">
        <div class="stat__label">Profitable after costs?</div>
        <div class="stat__value">No</div>
        <p class="stat__text">Trading on the forecast earns ${fx(Math.min(...be), 2)}–${fx(Math.max(...be), 2)} bps per trade before costs, against a ${fx(D.fee_bps, 0)} bps taker fee.</p>
      </div>`;
    $("#fact-sample").textContent = `${D.sample.in_sample.length} days per symbol (${D.sample.in_sample[0]} to ${D.sample.in_sample.at(-1)})`;
  }

  // ---------- scorecard ----------
  function badge(ok) {
    return `<span class="badge badge--${ok ? "pass" : "fail"}">${ok ? "✓ Pass" : "✗ Fail"}</span>`;
  }

  function renderScorecard() {
    const c = D.contemporaneous;
    const p = D.predictive;
    const rows = [
      { group: "Explains: the same interval (exchange clock, all 31 days)" },
      { id: "H1", q: "Does order flow line up with same-interval price moves?", d: "The core Cont–Kukanov–Stoikov result.",
        crit: "Positive slope in ≥ 95% of windows", cell: (s) => [c[s].verdicts.H1 === "PASS",
          `β > 0 in ${pct(c[s].beta_pos_share)} · R² ${fx(c[s].r2[0])}`, ci(c[s].r2[1], c[s].r2[2])] },
      { id: "H2", q: "Is the relation a straight line?", d: "Adds a curvature term OFI·|OFI|.",
        crit: "Curvature adds < 0.02 to median R²", cell: (s) => [c[s].verdicts.H2 === "PASS", `ΔR² ${signed(c[s].h2[0], 3)}`, ci(c[s].h2[1], c[s].h2[2], 3)] },
      { id: "H3", q: "Does price impact scale like 1/depth?", d: "Thicker books should absorb flow with smaller moves.",
        crit: "λ̂ in [0.7, 1.3] and its interval narrower than 0.6", cell: (s) => [c[s].verdicts.H3 === "PASS", `λ̂ ${fx(c[s].lam[0])}`, ci(c[s].lam[1], c[s].lam[2])] },
      { id: "H4", q: "Does order flow beat trades alone?", d: "Trade imbalance ignores new and cancelled orders.",
        crit: "R²(OFI) − R²(trades) interval above 0", cell: (s) => [c[s].verdicts.H4 === "PASS", `${signed(c[s].h4[0])} R²`, ci(c[s].h4[1], c[s].h4[2])] },
      { group: "Predicts: the next interval (receive clock, 100 ms latency, 6 held-out days)" },
      { id: "H5", q: "Does it forecast the next 10 seconds?", d: "Frozen slope from training days, run once.",
        crit: "Out-of-sample R² > 0", cell: (s) => [p[s].verdict === "PASS", `R² ${fx(p[s].oos_r2[0], 4)}`, ci(p[s].oos_r2[1], p[s].oos_r2[2], 4)] },
      { id: "H6", q: "Does the forecast survive trading costs?", d: "Hold the forecast's sign for 10 s, pay fee + half spread.",
        crit: "Reported as a break-even cost (prior: fails)", cell: (s) => {
          const cost = D.fee_bps + p[s].median_half_spread_bps;
          return [p[s].break_even_bps > cost, `${fx(p[s].break_even_bps)} bps edge`, `vs ${fx(cost)} bps cost`];
        } },
    ];
    const body = rows.map((r) => {
      if (r.group) return `<tr class="group-row"><td colspan="${2 + D.symbols.length}">${esc(r.group)}</td></tr>`;
      const cells = D.symbols.map((s) => {
        const [ok, v, sub] = r.cell(s);
        return `<td>${badge(ok)}<span class="cell__v">${v}</span><span class="cell__ci">${sub}</span></td>`;
      }).join("");
      return `<tr><td><div class="hyp"><span class="hyp__id">${r.id}</span><div><div class="hyp__q">${esc(r.q)}</div><div class="hyp__d">${esc(r.d)}</div></div></div></td><td>${esc(r.crit)}</td>${cells}</tr>`;
    }).join("");
    $("#scorecard-table thead tr").innerHTML = `<th scope="col">Hypothesis</th><th scope="col">Pass if</th>${D.symbols.map((s) => `<th scope="col">${s}</th>`).join("")}`;
    $("#scorecard-table tbody").innerHTML = body;
  }

  // ---------- tabs ----------
  function renderTabs() {
    $("#symbol-tabs").innerHTML = D.symbols.map((s) => `<button class="tab" role="tab" data-sym="${s}" aria-selected="${s === state.sym}" tabindex="${s === state.sym ? 0 : -1}" style="color:${symColor(s)}"><span class="dot"></span><span style="color:var(--ink)">${coin(s)}</span></button>`).join("");
  }

  function bindTabs() {
    const tabs = $("#symbol-tabs");
    tabs.addEventListener("click", (e) => {
      const b = e.target.closest(".tab");
      if (!b) return;
      state.sym = b.dataset.sym;
      tabs.querySelectorAll(".tab").forEach((t) => {
        t.setAttribute("aria-selected", String(t.dataset.sym === state.sym));
        t.tabIndex = t.dataset.sym === state.sym ? 0 : -1;
      });
      renderSymbolCharts();
    });
    tabs.addEventListener("keydown", (e) => {
      if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
      const i = D.symbols.indexOf(state.sym);
      const next = D.symbols[(i + (e.key === "ArrowRight" ? 1 : D.symbols.length - 1)) % D.symbols.length];
      tabs.querySelector(`[data-sym="${next}"]`).click();
      tabs.querySelector(`[data-sym="${next}"]`).focus();
    });
  }

  // ---------- explore charts ----------
  function chartDays() {
    const box = $("#chart-days");
    const sym = state.sym;
    const days = D.explore[sym]?.per_day || [];
    if (!days.length) return emptyChart(box, "No per-day results for this symbol");
    const f = frame(box);
    const t = days.map((d) => Date.parse(d.day));
    const x = linear([t[0], t.at(-1)], [f.x0 + 6, f.x1 - 6]);
    const y = linear([0, 1], [f.y0, f.y1]);
    yAxis(f, y, [0, 0.25, 0.5, 0.75, 1], (v) => v.toFixed(2), "median R²");
    const ax = el("g", { class: "axis" }, f.svg);
    for (const d of days) {
      const [yy, mm] = d.day.split("-");
      const narrow = f.w < 560;
      if (mm === "01" || (!narrow && mm === "07")) text(ax, x(Date.parse(d.day)), f.y0 + 18, narrow ? yy : `${yy}-${mm}`, { "text-anchor": "middle" });
    }
    const color = symColor(sym);
    const path = (key) => days.map((d, i) => `${i ? "L" : "M"}${x(t[i]).toFixed(1)},${y(d[key]).toFixed(1)}`).join("");
    el("path", { d: path("r2_ti"), fill: "none", stroke: css("--ti"), "stroke-width": 1.8, "stroke-dasharray": "5 4" }, f.svg);
    el("path", { d: path("r2_ofi"), fill: "none", stroke: color, "stroke-width": 2.4, "stroke-linejoin": "round" }, f.svg);
    days.forEach((d, i) => el("circle", { cx: x(t[i]), cy: y(d.r2_ofi), r: 3, fill: color }, f.svg));
    const hl = el("line", { y1: f.y1, y2: f.y0, class: "hover-line", visibility: "hidden" }, f.svg);
    const dot = el("circle", { r: 5, fill: color, stroke: css("--surface"), "stroke-width": 2, visibility: "hidden" }, f.svg);
    hoverLayer(f, (evt, px) => {
      const tv = x.invert(px);
      let i = 0;
      for (let j = 1; j < t.length; j++) if (Math.abs(t[j] - tv) < Math.abs(t[i] - tv)) i = j;
      const d = days[i];
      hl.setAttribute("x1", x(t[i])); hl.setAttribute("x2", x(t[i])); hl.setAttribute("visibility", "visible");
      dot.setAttribute("cx", x(t[i])); dot.setAttribute("cy", y(d.r2_ofi)); dot.setAttribute("visibility", "visible");
      showTip(evt, `<b>${d.day}</b><br>Order flow R² ${fx(d.r2_ofi)}<br>Trades-only R² ${fx(d.r2_ti)}<br>${d.windows} windows · depth ${fx(d.depth, d.depth < 10 ? 2 : 0)} ${coin(sym)}<br>Spread > 1 tick ${pct(d.gt1, 1)} of the time`);
    }, () => { hl.setAttribute("visibility", "hidden"); dot.setAttribute("visibility", "hidden"); });
    box.setAttribute("aria-label", `${sym}: median R² by day, order flow ${fx(Math.min(...days.map((d) => d.r2_ofi)))} to ${fx(Math.max(...days.map((d) => d.r2_ofi)))}, trade imbalance ${fx(Math.min(...days.map((d) => d.r2_ti)))} to ${fx(Math.max(...days.map((d) => d.r2_ti)))}`);
    $("#legend-days").innerHTML = `<span style="color:${color}"><i></i><span style="color:var(--muted)">Order-flow imbalance</span></span><span style="color:${css("--ti")}"><i class="dashed"></i><span style="color:var(--muted)">Trade imbalance (executed trades only)</span></span>`;
  }

  function logTicks(lo, hi) {
    const out = [];
    for (let e = Math.floor(Math.log10(lo)); e <= Math.ceil(Math.log10(hi)); e++)
      for (const m of [1, 2, 5]) { const v = m * 10 ** e; if (v >= lo && v <= hi) out.push(v); }
    return out;
  }
  const short = (v) => (v >= 1000 ? `${v / 1000}k` : v >= 1 ? String(v) : String(+v.toPrecision(2)));

  function chartDepth() {
    const box = $("#chart-depth");
    const sym = state.sym;
    const W = D.explore[sym]?.windows;
    const idx = W ? W.beta.map((_, i) => i).filter((i) => W.beta[i] > 0 && W.depth[i] > 0) : [];
    if (!idx.length) return emptyChart(box, "No window results for this symbol");
    const f = frame(box, { t: 12, r: 16, b: 40, l: 50 });
    const q = (arr, p) => { const s = [...arr].sort((a, b) => a - b); return s[Math.floor(p * (s.length - 1))]; };
    const dep = idx.map((i) => W.depth[i]);
    const bet = idx.map((i) => W.beta[i]);
    const [dx0, dx1] = [q(dep, 0.002) / 1.15, q(dep, 0.998) * 1.15];
    const [by0, by1] = [q(bet, 0.002) / 1.3, q(bet, 0.998) * 1.3];
    const x = logScale([dx0, dx1], [f.x0, f.x1]);
    const y = logScale([by0, by1], [f.y0, f.y1]);
    const g = el("g", { class: "axis" }, f.svg);
    for (const v of logTicks(by0, by1)) { el("line", { x1: f.x0, x2: f.x1, y1: y(v), y2: y(v), class: "gridline" }, g); text(g, f.x0 - 8, y(v) + 4, short(v), { "text-anchor": "end" }); }
    for (const v of logTicks(dx0, dx1)) text(g, x(v), f.y0 + 16, short(v), { "text-anchor": "middle" });
    text(g, (f.x0 + f.x1) / 2, f.h - 4, `average depth (${coin(sym)})`, { class: "axis-title", "text-anchor": "middle" });
    text(g, 12, (f.y0 + f.y1) / 2, "β (ticks per coin of flow)", { class: "axis-title", transform: `rotate(-90 12 ${(f.y0 + f.y1) / 2})`, "text-anchor": "middle" });
    const color = symColor(sym);
    const clip = el("clipPath", { id: "clip-depth" }, el("defs", {}, f.svg));
    el("rect", { x: f.x0, y: f.y1, width: f.x1 - f.x0, height: f.y0 - f.y1 }, clip);
    const pts = el("g", { "clip-path": "url(#clip-depth)" }, f.svg);
    const xy = idx.map((i) => [x(W.depth[i]), y(W.beta[i])]);
    for (const [px, py] of xy) el("circle", { cx: px.toFixed(1), cy: py.toFixed(1), r: 2.2, fill: color, "fill-opacity": 0.35 }, pts);
    const { a, lam } = D.explore[sym].depth_fit;
    const line = (fn) => { const n = 40; let s = ""; for (let k = 0; k <= n; k++) { const d = dx0 * (dx1 / dx0) ** (k / n); s += `${k ? "L" : "M"}${x(d).toFixed(1)},${y(fn(d)).toFixed(1)}`; } return s; };
    const gm = Math.exp(dep.reduce((s, v) => s + Math.log(v), 0) / dep.length);
    const fit = (d) => Math.exp(a) * d ** -lam;
    el("path", { d: line((d) => fit(gm) * (d / gm) ** -1), fill: "none", stroke: css("--faint"), "stroke-width": 1.4, "stroke-dasharray": "5 4" }, pts);
    el("path", { d: line(fit), fill: "none", stroke: css("--ink"), "stroke-width": 2 }, pts);
    const ring = el("circle", { r: 5, fill: "none", stroke: css("--ink"), "stroke-width": 1.5, visibility: "hidden" }, f.svg);
    hoverLayer(f, (evt, px, py) => {
      let best = 0, bd = Infinity;
      for (let k = 0; k < xy.length; k++) { const dd = (xy[k][0] - px) ** 2 + (xy[k][1] - py) ** 2; if (dd < bd) { bd = dd; best = k; } }
      if (bd > 900) { hideTip(); ring.setAttribute("visibility", "hidden"); return; }
      const i = idx[best];
      ring.setAttribute("cx", xy[best][0]); ring.setAttribute("cy", xy[best][1]); ring.setAttribute("visibility", "visible");
      showTip(evt, `<b>${W.day[i]}</b> window<br>β ${fx(W.beta[i], 3)} ticks per ${coin(sym)}<br>depth ${fx(W.depth[i], W.depth[i] < 10 ? 2 : 0)} ${coin(sym)} · R² ${fx(W.r2[i])}`);
    }, () => ring.setAttribute("visibility", "hidden"));
    const c = D.contemporaneous[sym];
    const ok = c.verdicts.H3 === "PASS";
    $("#note-depth").innerHTML = `Fitted λ̂ = <b>${fx(c.lam[0])}</b> ${ci(c.lam[1], c.lam[2])}. ${ok ? "Consistent with λ = 1 (solid vs dashed slope −1 reference)." : "The point estimate is plausible but the interval is too wide: depth varies too little across windows to pin the slope down."}`;
    box.setAttribute("aria-label", `${sym}: window slope against depth on log scales; fitted lambda ${fx(c.lam[0])}`);
  }

  function bars(box, items, { yDomain, format, color, labelFormat }) {
    const f = frame(box, { t: 18, r: 10, b: 34, l: 40 });
    const y = linear(yDomain, [f.y0, f.y1]);
    const ticks = [yDomain[0], (yDomain[0] + yDomain[1]) / 2, yDomain[1]];
    yAxis(f, y, ticks, format);
    const band = (f.x1 - f.x0) / items.length;
    const bw = Math.min(56, band * 0.6);
    items.forEach((it, i) => {
      const cx = f.x0 + band * (i + 0.5);
      const top = y(Math.max(it.v, 0));
      el("rect", { x: cx - bw / 2, y: top, width: bw, height: Math.max(1, y(0) - top), rx: 4, fill: it.color || color, "fill-opacity": it.dim ? 0.45 : 1 }, f.svg);
      text(f.svg, cx, top - 6, (labelFormat || format)(it.v), { class: "label", "text-anchor": "middle" });
      text(f.svg, cx, f.y0 + 16, it.label, { class: "label label--muted", "text-anchor": "middle" });
      if (it.tip) {
        const hit = el("rect", { x: cx - band / 2, y: f.y1, width: band, height: f.y0 - f.y1 + 20, fill: "transparent" }, f.svg);
        hit.addEventListener("pointermove", (e) => showTip(e, it.tip));
        hit.addEventListener("pointerleave", hideTip);
      }
    });
  }

  function chartSpecs() {
    const sym = state.sym;
    const s = D.contemporaneous[sym]?.specs;
    if (!s) return emptyChart($("#chart-specs"), "No robustness results");
    const color = symColor(sym);
    const label = { "robust 1s/30min": "1 s buckets", "main 10s/30min": "10 s (main)", "robust 60s/2h": "60 s buckets" };
    const order = ["robust 1s/30min", "main 10s/30min", "robust 60s/2h"].filter((k) => k in s);
    bars($("#chart-specs"), order.map((k) => ({ label: label[k], v: s[k], dim: !k.startsWith("main"), tip: `<b>${label[k]}</b><br>median window R² ${fx(s[k], 3)}` })),
      { yDomain: [0, 1], format: (v) => v.toFixed(1), labelFormat: (v) => v.toFixed(2), color });
    $("#chart-specs").setAttribute("aria-label", `${sym}: median R² by bucket size: ${order.map((k) => `${label[k]} ${fx(s[k])}`).join(", ")}`);
  }

  function chartQuintiles() {
    const sym = state.sym;
    const qd = D.explore[sym]?.spread_quintiles;
    if (!qd) return emptyChart($("#chart-quintiles"), "No exploratory results");
    const color = symColor(sym);
    bars($("#chart-quintiles"), qd.r2.map((v, i) => ({ label: pct(qd.share[i], qd.share[i] < 0.1 ? 1 : 0), v,
      tip: `<b>Quintile ${i + 1}</b> of windows<br>spread > 1 tick ${pct(qd.share[i], 1)} of the time (median)<br>median R² ${fx(v, 3)}` })),
      { yDomain: [0, 1], format: (v) => v.toFixed(1), labelFormat: (v) => v.toFixed(2), color });
    $("#chart-quintiles").setAttribute("aria-label", `${sym}: median R² by spread quintile, from ${fx(qd.r2[0])} to ${fx(qd.r2.at(-1))}`);
  }

  // ---------- prediction ----------
  function chartOos() {
    const box = $("#chart-oos");
    const f = frame(box, { t: 14, r: 16, b: 34, l: 56 });
    const lo = -0.12, hi = 0.02;
    const y = linear([lo, hi], [f.y0, f.y1]);
    yAxis(f, y, [-0.12, -0.08, -0.04, 0], (v) => fx(v, 2), "out-of-sample R²");
    const band = (f.x1 - f.x0) / D.symbols.length;
    D.symbols.forEach((s, i) => {
      const [v, l, h] = D.predictive[s].oos_r2;
      const cx = f.x0 + band * (i + 0.5);
      const color = symColor(s);
      const clipped = l < lo;
      el("line", { x1: cx, x2: cx, y1: y(Math.max(l, lo)), y2: y(Math.min(h, hi)), stroke: color, "stroke-width": 2.5 }, f.svg);
      if (!clipped) el("line", { x1: cx - 7, x2: cx + 7, y1: y(l), y2: y(l), stroke: color, "stroke-width": 2.5 }, f.svg);
      else el("path", { d: `M${cx - 6},${y(lo) - 8} L${cx},${y(lo)} L${cx + 6},${y(lo) - 8}`, fill: "none", stroke: color, "stroke-width": 2.5 }, f.svg);
      el("line", { x1: cx - 7, x2: cx + 7, y1: y(h), y2: y(h), stroke: color, "stroke-width": 2.5 }, f.svg);
      el("circle", { cx, cy: y(v), r: 6, fill: color, stroke: css("--surface"), "stroke-width": 2 }, f.svg);
      text(f.svg, cx + 12, y(v) + 4, fx(v, 4), { class: "label" });
      if (clipped) text(f.svg, cx + 12, y(lo) - 2, `to ${fx(l, 2)}`, { class: "label label--muted" });
      text(f.svg, cx, f.y0 + 18, coin(s), { class: "label label--muted", "text-anchor": "middle" });
      const hit = el("rect", { x: cx - band / 2, y: f.y1, width: band, height: f.y0 - f.y1, fill: "transparent" }, f.svg);
      hit.addEventListener("pointermove", (e) => showTip(e, `<b>${s}</b>, held-out days<br>R² ${fx(v, 4)} ${ci(l, h, 4)}<br>${v > 0 ? "beats" : "does not beat"} the zero forecast`));
      hit.addEventListener("pointerleave", hideTip);
    });
    text(f.svg, f.x1, y(0) - 6, "zero forecast", { class: "label label--muted", "text-anchor": "end" });
    box.setAttribute("aria-label", `Held-out out-of-sample R²: ${D.symbols.map((s) => `${coin(s)} ${fx(D.predictive[s].oos_r2[0], 4)}`).join(", ")}`);

    const td = (v, d = 4) => `<td class="${v > 0 ? "pos-v" : v < 0 ? "neg-v" : ""}">${fx(v, d)}</td>`;
    $("#oos-table").innerHTML = `<thead><tr><th>Symbol</th><th>Held-out test</th><th>Validation</th><th>Walk-forward</th></tr></thead><tbody>${
      D.symbols.map((s) => { const p = D.predictive[s]; return `<tr><td>${s}</td>${td(p.oos_r2[0])}${td(p.validation_oos_r2[0])}${td(p.walk_forward_oos_r2)}</tr>`; }).join("")}</tbody>`;
  }

  function chartCost() {
    const box = $("#chart-cost");
    const f = frame(box, { t: 8, r: 64, b: 28, l: 52 });
    const rows = D.symbols.map((s) => ({ s, edge: D.predictive[s].break_even_bps, cost: D.fee_bps + D.predictive[s].median_half_spread_bps }));
    const max = Math.max(...rows.map((r) => r.cost)) * 1.05;
    const x = linear([0, max], [f.x0, f.x1]);
    const g = el("g", { class: "axis" }, f.svg);
    for (let v = 0; v <= max; v += 2) { el("line", { x1: x(v), x2: x(v), y1: f.y1, y2: f.y0, class: v ? "gridline" : "zero" }, g); text(g, x(v), f.y0 + 16, `${v} bps`, { "text-anchor": "middle" }); }
    const band = (f.y0 - f.y1) / rows.length;
    const bh = Math.min(16, band * 0.3);
    rows.forEach((r, i) => {
      const cy = f.y1 + band * (i + 0.5);
      text(f.svg, f.x0 - 8, cy + 4, coin(r.s), { class: "label label--muted", "text-anchor": "end" });
      el("rect", { x: x(0), y: cy - bh - 2, width: Math.max(2, x(r.edge) - x(0)), height: bh, rx: 3, fill: css("--predict") }, f.svg);
      text(f.svg, x(r.edge) + 6, cy - 5, `edge ${fx(r.edge)}`, { class: "label" });
      el("rect", { x: x(0), y: cy + 2, width: x(r.cost) - x(0), height: bh, rx: 3, fill: css("--faint"), "fill-opacity": 0.55 }, f.svg);
      text(f.svg, x(r.cost) + 6, cy + bh - 2, `cost ${fx(r.cost)}`, { class: "label label--muted" });
      const hit = el("rect", { x: f.x0, y: cy - band / 2, width: f.x1 - f.x0, height: band, fill: "transparent" }, f.svg);
      hit.addEventListener("pointermove", (e) => showTip(e, `<b>${r.s}</b><br>Edge before costs ${fx(r.edge, 3)} bps per trade<br>Cost ${fx(D.fee_bps, 1)} bps fee + ${fx(r.cost - D.fee_bps, 3)} bps half spread`));
      hit.addEventListener("pointerleave", hideTip);
    });
    const ratios = rows.map((r) => r.cost / r.edge);
    const maxEdge = Math.max(...rows.map((r) => r.edge));
    $("#note-cost").textContent = `The cost of one trade is ${Math.round(Math.min(...ratios))}–${Math.round(Math.max(...ratios))} times the average edge. Any cost above ${fx(maxEdge)} bps per trade wipes the edge out.`;
    box.setAttribute("aria-label", `Edge versus cost per trade: ${rows.map((r) => `${coin(r.s)} edge ${fx(r.edge)} bps, cost ${fx(r.cost)} bps`).join("; ")}`);
  }

  function modelsTable() {
    const sym = state.sym;
    const models = D.predictive[sym]?.models || [];
    $("#models-symbol").textContent = `· ${sym}`;
    if (!models.length) { $("#models-table").innerHTML = "<tbody><tr><td>No model results for this symbol.</td></tr></tbody>"; return; }
    const td = (v, d) => `<td class="${v > 0 ? "pos-v" : v < 0 ? "neg-v" : ""}">${fx(v, d)}</td>`;
    $("#models-table").innerHTML = `<thead><tr><th>Model</th><th>Latency</th><th>Out-of-sample R²</th><th>Edge per trade (bps)</th></tr></thead><tbody>${
      models.map((m) => `<tr class="${m.model === "ofi" && m.L_ms === 100 ? "is-main" : ""}"><td>${esc(MODEL_NAMES[m.model] || m.model)}</td><td>${m.L_ms} ms</td>${td(m.oos_r2, 4)}${td(m.break_even_bps, 3)}</tr>`).join("")}</tbody>`;
  }

  // ---------- wiring ----------
  function renderSymbolCharts() {
    hideTip();
    chartDays();
    chartDepth();
    chartSpecs();
    chartQuintiles();
    modelsTable();
  }

  function renderAll() {
    renderSymbolCharts();
    chartOos();
    chartCost();
  }

  function fail(message) {
    const box = $("#app-error");
    box.hidden = false;
    box.innerHTML = `<div class="error"><h2>Results could not be loaded</h2><p>${message}</p></div>`;
    document.querySelectorAll(".skeleton").forEach((n) => n.classList.remove("skeleton"));
    $("#hero-stats").innerHTML = "";
  }

  if (!D || !Array.isArray(D.symbols) || !D.symbols.length) {
    fail("<code>data.js</code> is missing or empty. Generate it from the repository root with <code>ofi site</code>, then reload.");
    return;
  }
  try {
    state.sym = D.symbols[0];
    renderHero();
    renderScorecard();
    renderTabs();
    bindTabs();
    renderAll();
  } catch (err) {
    console.error(err);
    fail(`Unexpected data format (${esc(err.message)}). Regenerate <code>data.js</code> with <code>ofi site</code>.`);
    return;
  }

  let timer;
  const ro = new ResizeObserver(() => { clearTimeout(timer); timer = setTimeout(renderAll, 120); });
  document.querySelectorAll(".chart").forEach((c) => ro.observe(c));
  window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", () => { renderTabs(); renderAll(); });
})();
